TREE = {"arch1": {"db1": {"coll1": ["rec1", "rec2"]}}}
def zoom(path):
    node, ok = TREE, []
    for seg in path:
        if isinstance(node, dict) and seg in node:
            node, ok = node[seg], ok + [seg]
        elif isinstance(node, list) and seg in node:
            ok = ok + [seg]; node = None; break
        else:
            return ok, False
    return ok, True
for p in [["arch1", "db1", "coll1", "rec2"], ["arch1", "db9"]]:
    print(p, "->", zoom(p))

